html:
{% set d = dados_recibo(doc) %}
{% set timbrado = letter_head and not no_letterhead %}
<style>
	.recibo { color: #1f2328; font-size: 9.5pt; line-height: 1.4; }
	.recibo table { width: 100%; border-collapse: collapse; }
	.recibo td, .recibo th { border: 0 !important; padding: 0; vertical-align: top; background: transparent !important; color: inherit !important; }
	.recibo .logo { max-height: 52px; max-width: 150px; margin-bottom: 8px; }
	.recibo .empresa { font-size: 11pt; font-weight: 700; }
	.recibo .suave { color: #5c636b !important; }
	.recibo .titulo { font-size: 17pt; font-weight: 700; line-height: 1.15; }
	.recibo .direita { text-align: right; }
	.recibo .regra { border-top: 3px solid #1f2328; margin: 12px 0 14px; }
	.recibo .ident td { padding: 2px 0; }
	.recibo .ident td.rotulo { color: #5c636b !important; width: 112px; white-space: nowrap; padding-right: 10px; }
	.recibo .ident td.valor { font-weight: 600; }
	.recibo .movimentos { margin-top: 18px; }
	.recibo .movimentos th { font-size: 8.5pt; font-weight: 700; text-align: left; padding: 0 0 6px; border-bottom: 1.5px solid #1f2328 !important; }
	.recibo .movimentos td { padding: 6px 0; border-bottom: 1px solid #dfe2e6 !important; }
	.recibo .movimentos .num { text-align: right; width: 24%; white-space: nowrap; }
	.recibo .movimentos tr.total td { font-weight: 700; border-top: 1.5px solid #1f2328 !important; border-bottom: 0 !important; }
	.recibo .liquido { margin-top: 12px; }
	.recibo .liquido td { padding: 10px 12px; background: #1f2328 !important; color: #fff !important; font-size: 11.5pt; font-weight: 700; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
	.recibo .declaracao { margin-top: 26px; font-style: italic; }
	.recibo .assinaturas td { width: 46%; padding-top: 46px; font-size: 8.5pt; color: #5c636b !important; }
	.recibo .assinaturas td.meio { width: 8%; }
	.recibo .linha { border-top: 1px solid #1f2328; padding-top: 4px; }
</style>

<div class="recibo">
	{% if timbrado %}<div class="letter-head">{{ letter_head }}</div>{% endif %}

	<table>
		<tr>
			<td>
				{% if not timbrado %}
				{% if d.logo %}<img class="logo" src="{{ d.logo }}"><br>{% endif %}
				<div class="empresa">{{ d.empresa | e }}</div>
				{% if d.endereco %}<div class="suave">{{ d.endereco | e }}</div>{% endif %}
				{% if d.cidade %}<div class="suave">{{ d.cidade | e }}</div>{% endif %}
				{% if d.nuit %}<div class="suave">NUIT: {{ d.nuit | e }}</div>{% endif %}
				{% endif %}
			</td>
			<td class="direita">
				<div class="titulo">Recibo de Salário</div>
				<div style="font-weight: 600;">{{ d.periodo }}</div>
				<div class="suave" style="font-size: 8.5pt;">{{ doc.name | e }}</div>
			</td>
		</tr>
	</table>

	<div class="regra"></div>

	<table>
		<tr>
			<td style="width: 54%; padding-right: 24px;">
				<table class="ident">
					<tr><td class="rotulo">Nome</td><td class="valor">{{ doc.employee_name | e }}</td></tr>
					<tr><td class="rotulo">Nº Funcionário</td><td class="valor">{{ doc.employee | e }}</td></tr>
					{% if doc.designation %}<tr><td class="rotulo">Função</td><td class="valor">{{ doc.designation | e }}</td></tr>{% endif %}
					{% if doc.department %}<tr><td class="rotulo">Departamento</td><td class="valor">{{ doc.department | e }}</td></tr>{% endif %}
					{% if doc.bank_name %}<tr><td class="rotulo">Banco</td><td class="valor">{{ doc.bank_name | e }}</td></tr>{% endif %}
					{% if doc.bank_account_no %}<tr><td class="rotulo">Conta</td><td class="valor">{{ doc.bank_account_no | e }}</td></tr>{% endif %}
				</table>
			</td>
			<td>
				<table class="ident">
					<tr><td class="rotulo">Salário Mensal</td><td class="valor">{{ d.salario_mensal }}</td></tr>
					<tr><td class="rotulo">Período</td><td class="valor">{{ frappe.utils.formatdate(doc.start_date) }} a {{ frappe.utils.formatdate(doc.end_date) }}</td></tr>
					<tr><td class="rotulo">Dias de Referência</td><td class="valor">{{ d.dias_referencia }}</td></tr>
					<tr><td class="rotulo">Dias Remunerados</td><td class="valor">{{ d.dias_remunerados }}</td></tr>
					{% if d.faltas %}<tr><td class="rotulo">Faltas</td><td class="valor">{{ d.faltas }}</td></tr>{% endif %}
				</table>
			</td>
		</tr>
	</table>

	<table class="movimentos">
		<thead>
			<tr>
				<th>Descrição</th>
				<th class="num">Remunerações</th>
				<th class="num">Descontos</th>
			</tr>
		</thead>
		<tbody>
			{% for l in d.linhas %}
			<tr>
				<td>{{ l.descricao | e }}</td>
				<td class="num">{{ l.remuneracao }}</td>
				<td class="num">{{ l.desconto }}</td>
			</tr>
			{% endfor %}
			<tr class="total">
				<td>Total</td>
				<td class="num">{{ d.total_remuneracoes }}</td>
				<td class="num">{{ d.total_descontos }}</td>
			</tr>
		</tbody>
	</table>

	<table class="liquido">
		<tr>
			<td>Líquido a Receber</td>
			<td class="direita">{{ doc.currency or "MZN" }} {{ d.liquido }}</td>
		</tr>
	</table>

	<div class="declaracao">Declaro que recebi a quantia constante neste recibo.</div>

	<table class="assinaturas">
		<tr>
			<td><div class="linha">O Funcionário</div></td>
			<td class="meio"></td>
			<td><div class="linha">A Entidade Empregadora</div></td>
		</tr>
	</table>
</div>
